edits.replacement:
/* v16.xx, THE STYLING PASS, STAGE B: THE TITLE. A vignette instead of a flat wash, so the Undercroft still shows through
   (v17.83) and the column reads; a wordmark with a gold gradient and a glow; the three step cards as glass cards. */
#title.on { background:radial-gradient(ellipse 70% 62% at 50% 42%, rgba(9,15,40,.60) 0%, rgba(9,15,40,.84) 70%, rgba(5,8,22,.96) 100%); }
#title .wordmark{ font-family:'Titan One','Rubik',sans-serif; font-size:64px; letter-spacing:.16em; line-height:1;
  background:linear-gradient(180deg,#ffe9a8 0%,#ffc04a 55%,#e08a1a 100%); -webkit-background-clip:text; background-clip:text; color:transparent;
  filter:drop-shadow(0 4px 0 rgba(0,0,0,.55)) drop-shadow(0 0 22px rgba(255,192,74,.28)); }
#title .tcard{ border:1px solid rgba(127,146,216,.35); border-radius:10px; padding:14px 16px;
  background:linear-gradient(180deg,rgba(127,146,216,.10),rgba(0,0,0,.32)); box-shadow:0 10px 30px rgba(0,0,0,.25), inset 0 1px 0 rgba(255,255,255,.06); }
#title .tstep{ font-size:11px; letter-spacing:.22em; color:var(--amber); font-weight:700; }
#title .tcard .tbody{ font-size:12px; color:var(--ash); margin-top:6px; line-height:1.5; }

check:
{v:'VER',what:'stage B of the styling pass: the title wordmark is a gold gradient clipped to the letters, the three step cards are rounded glass cards, and the title backdrop is a vignette that still lets the Undercroft show through',
 run:function(){
   var t=document.getElementById('title'), wm=t&&t.querySelector('.wordmark'), cards=t?t.querySelectorAll('.tcard'):[], bad=[], s, was;
   if(!t) return 'SKIP: no title';
   if(!wm) return 'the title has no wordmark';
   was=t.classList.contains('on'); if(!was) t.classList.add('on');
   try{
     s=getComputedStyle(wm);
     if(!/gradient/.test(s.backgroundImage)) bad.push('the wordmark is flat');
     if(!/text/.test(String(s.webkitBackgroundClip||s.backgroundClip))) bad.push('the gradient is not clipped to the letters');
     if(cards.length!==3) bad.push('the title has '+cards.length+' step cards, not 3');
     else { s=getComputedStyle(cards[0]); if(parseFloat(s.borderTopLeftRadius)<8) bad.push('the step cards are square'); if(!/gradient/.test(s.backgroundImage)) bad.push('the step cards are flat'); }
     s=getComputedStyle(t);
     if(!/gradient/.test(s.backgroundImage)) bad.push('the title backdrop is a flat wash');
   }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
   finally{ if(!was) t.classList.remove('on'); }
   return bad.length?bad.join('; '):null; }},
